<script>
document.addEventListener(
  "DOMContentLoaded",
  function () {

    const params =
      new URLSearchParams(
        window.location.search
      );

    if (
      params.get("embed") === "1"
    ) {
      document.body.classList.add(
        "tutorial-embedded"
      );
    }
  }
);
</script>
